package com.vandorlabs.segmented;
public final class SegmentedCellArtworkTest {
 public static void main(String[] args){int checks=0;for(int global:new int[]{-1,0,7,100,Integer.MIN_VALUE}){if(SegmentedCellArtwork.INHERITED.effective(global)!=global)throw new AssertionError("old default changed");checks++;for(int local:new int[]{-1,0,7,100,Integer.MIN_VALUE}){SegmentedCellArtwork value=SegmentedCellArtwork.explicit(local,x->true);if(value.effective(global)!=local||!value.overridden||!value.equals(SegmentedCellArtwork.explicit(local,x->true)))throw new AssertionError("cell choice changed");checks++;}}try{SegmentedCellArtwork.explicit(7,x->false);throw new AssertionError("invalid material accepted");}catch(IllegalArgumentException expected){checks++;}if(SegmentedCellArtwork.INHERITED.equals(SegmentedCellArtwork.explicit(-1,x->true)))throw new AssertionError("default artwork must differ from inheritance");checks++;System.out.println("Segmented cell artwork PASS "+checks+" checks");}
}
